def parse_input(input_string):
    """
    Parses a string containing multiple tokens separated by whitespace into their corresponding data types.

    :param input_string: A string containing tokens separated by whitespace.
    :return: A list of parsed values, one for each token.
    """
    def parse_single_token(token):
        """
        Parses a single token into its corresponding data type.

        :param token: A string representing a single token.
        :return: The parsed value of the token.
        """
        if token == '#f':
            return False
        elif token == '#t':
            return True
        else:
            try:
                return int(token)
            except ValueError:
                try:
                    return float(token)
                except ValueError:
                    return token

    parsed_tokens = []
    current_token = []
    in_token = False

    for char in input_string:
        if char.isspace():
            if in_token:
                parsed_tokens.append(parse_single_token(''.join(current_token)))
                current_token = []
                in_token = False
        else:
            current_token.append(char)
            in_token = True

    if in_token:
        parsed_tokens.append(parse_single_token(''.join(current_token)))

    return parsed_tokens
