def adjusted_scores(discussion_points, quiz_scores, performance_metrics=None, metric_weights=None):
    """
    Adjusts quiz scores based on students' performance across multiple metrics.

    Parameters:
    - discussion_points (dict): A dictionary of students' discussion points.
    - quiz_scores (dict): A dictionary of students' quiz scores.
    - performance_metrics (list of dict): A list of dictionaries containing scores for specific performance metrics.
    - metric_weights (dict): A dictionary mapping each performance metric to a weight.

    Returns:
    - adjusted_scores (dict): A dictionary of adjusted quiz scores.
    """
    if not performance_metrics or not metric_weights:
        if not discussion_points:
            return quiz_scores

        avg_discussion_points = sum(discussion_points.values()) / len(discussion_points)

        adjusted_scores = {
            student: score + (1 if discussion_points.get(student, 0) >= avg_discussion_points else 0)
            for student, score in quiz_scores.items()
        }

    else:
        student_weighted_averages = {}

        for student in quiz_scores.keys():
            total_weighted_score = 0
            total_weight = 0

            for metric in performance_metrics:
                metric_name = list(metric.keys())[0]
                score = metric[metric_name].get(student, 0)
                weight = metric_weights.get(metric_name, 0)

                total_weighted_score += score * weight
                total_weight += weight

            if total_weight > 0:
                weighted_average = total_weighted_score / total_weight
            else:
                weighted_average = 0

            student_weighted_averages[student] = weighted_average

        if student_weighted_averages:
            class_avg_weighted_score = sum(student_weighted_averages.values()) / len(student_weighted_averages)
        else:
            class_avg_weighted_score = 0

        adjusted_scores = {
            student: score + (1 if student_weighted_averages.get(student, 0) >= class_avg_weighted_score else 0)
            for student, score in quiz_scores.items()
        }

    return adjusted_scores
