def sha256_hash(s):
    """Compute the SHA-256 hash of a string."""
    return hashlib.sha256(s.encode('utf-8')).hexdigest()

def convert_data_dict_to_json(data_dict):
    """Convert the given data dictionary to a simplified JSON-compatible dictionary."""
    result = {}
    for key, value in data_dict.items():
        n_items = value.get('n_items', 0)
        items = value.get('items', [])

        if n_items > 0:
            if n_items == 1:
                item = items[0]
                if isinstance(item, str):
                    item = sha256_hash(item)
                result[key] = item
            else:
                hashed_items = [sha256_hash(item) if isinstance(item, str) else item for item in items]
                result[key] = hashed_items

    return result

