def generate_query_string(params):
    """
    Generates a query string for a REST API from a dictionary of parameters.

    Parameters:
    params (dict): A dictionary where keys are parameter names and values are parameter values.

    Returns:
    str: The generated query string.
    """
    def flatten_params(prefix, params):
        flat_list = []
        for key, value in params.items():
            if value is None:
                continue
            full_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                flat_list.extend(flatten_params(full_key, value))
            elif isinstance(value, list):
                for item in value:
                    flat_list.append((full_key, item))
            else:
                flat_list.append((full_key, value))
        return flat_list

    flat_params = flatten_params('', params)
    if not flat_params:
        return ''
    query_string = '&'.join(f"{key}={value}" for key, value in flat_params)
    return '?' + query_string
