def get_item_by_index_or_key(structure, keys):
    """
    Retrieves an item from a nested structure using a sequence of keys or indices.

    Args:
    structure (dict, list, tuple): The nested data structure to search.
    keys (str, int, tuple): A single key/index or a tuple of keys/indices.

    Returns:
    The value found at the specified location in the structure.

    Raises:
    TypeError: If an invalid type is encountered.
    KeyError: If a dictionary key is missing.
    IndexError: If an index is out of range.
    """
    if not isinstance(keys, tuple):
        keys = (keys,)

    def recursive_lookup(s, k):
        if not k:
            return s
        key = k[0]
        if isinstance(s, dict):
            if key not in s:
                raise KeyError(f"Key '{key}' not found in dictionary.")
            return recursive_lookup(s[key], k[1:])
        elif isinstance(s, (list, tuple)):
            if not isinstance(key, int) or key < 0 or key >= len(s):
                raise IndexError(f"Index '{key}' is out of range for sequence of length {len(s)}.")
            return recursive_lookup(s[key], k[1:])
        else:
            raise TypeError(f"Cannot access key/index '{key}' on object of type {type(s).__name__}")

    return recursive_lookup(structure, keys)
