import threading

class DataStream:
    def __init__(self):
        self.lock = threading.Lock()
        self.is_open = False

    def open(self) -> bool:
        with self.lock:
            if not self.is_open:
                self.is_open = True
                print("Connection opened.")
                return True
            else:
                print("Connection is already open.")
                return False

    def send(self, data: str) -> bool:
        with self.lock:
            if self.is_open:
                print(f"Data sent: {data}")
                return True
            else:
                print("Cannot send data: Connection is not open.")
                return False

    def close(self) -> bool:
        with self.lock:
            if self.is_open:
                self.is_open = False
                print("Connection closed.")
                return True
            else:
                print("Connection is already closed.")
                return False

def manage_connection(service: DataStream, data: str, action: str) -> bool:
    """
    Manages the connection to a DataStream service by performing the specified action.

    Parameters:
    - service: An instance of the DataStream class.
    - data: A string representing the data to be sent.
    - action: A string that can be "open", "send", or "close".

    Returns:
    - True if the action was successful.
    - False otherwise.
    """
    try:
        if action == "open":
            return service.open()
        elif action == "send":
            return service.send(data)
        elif action == "close":
            return service.close()
        else:
            print("Invalid action.")
            return False
    except Exception as e:
        print(f"An error occurred: {e}")
        return False
