def title_case_sentence(sentence: str, failure_string: str = 'N/A') -> str:
    """
    Converts a given sentence into title case according to specific rules.

    Parameters:
    sentence (str): The input string to be converted.
    failure_string (str): The string to return if the input is empty or None.

    Returns:
    str: The title-cased sentence or the failure string if applicable.
    """
    if not sentence:
        return failure_string

    def custom_title(word: str) -> str:
        word = word.strip()
        if not word:
            return word
        if word[0].isdigit():
            return word[0] + word[1:].lower()
        if "'" in word:
            parts = word.split("'")
            if len(parts) == 2 and parts[0] and parts[0][-1].islower():
                return parts[0].capitalize() + "'" + parts[1].lower()
        return word.capitalize()

    words = sentence.split()
    title_cased_words = [custom_title(word) for word in words]
    return ' '.join(title_cased_words)
