def convert_to_roman(number):
    """
    Convert an integer to its Roman numeral representation.

    :param number: Integer to convert (1 <= number <= 3999)
    :return: String representing the Roman numeral
    """
    result = ""
    while number > 0:
        if number >= 1000:
            result += "M"
            number -= 1000
        elif number >= 900:
            result += "CM"
            number -= 900
        elif number >= 500:
            result += "D"
            number -= 500
        elif number >= 400:
            result += "CD"
            number -= 400
        elif number >= 100:
            result += "C"
            number -= 100
        elif number >= 90:
            result += "XC"
            number -= 90
        elif number >= 50:
            result += "L"
            number -= 50
        elif number >= 40:
            result += "XL"
            number -= 40
        elif number >= 10:
            result += "X"
            number -= 10
        elif number >= 9:
            result += "IX"
            number -= 9
        elif number >= 5:
            result += "V"
