import unittest

def format_duration(seconds):
    """
    Formats a given number of seconds into a human-readable duration string.

    Args:
    seconds (int): The number of seconds to format.

    Returns:
    str: A string representing the duration in years, days, hours, minutes, and seconds.
    """
    if seconds == 0:
        return "now"

    time_units = [("year", 365 * 24 * 3600), ("day", 24 * 3600), ("hour", 3600), ("minute", 60), ("second", 1)]
    duration_str = []

    for unit, value in time_units:
        count = seconds // value
        if count > 0:
            seconds %= value
            duration_str.append(f"{count} {unit}{'s' if count > 1 else ''}")

    if len(duration_str) > 1:
        return ", ".join(duration_str[:-1]) + " and " + duration_str[-1]
    else:
        return duration_str[0]

class TestFormatDuration(unittest.TestCase):
    def test_zero_seconds(self):
        self.assertEqual(format_duration(0), "now")

    def test_one_second(self):
        self.assertEqual(format_duration(1), "1 second")

    def test_minutes(self):
        self.assertEqual(format_duration(60), "1 minute")
        self.assertEqual(format_duration(120), "2 minutes")

    def test_hours(self):
        self.assertEqual(format_duration(3600), "1 hour")
        self.assertEqual(format_duration(7200), "2 hours")

    def test_days(self):
        self.assertEqual(format_duration(86400), "1 day")
        self.assertEqual(format_duration(172800), "2 days")

    def test_years(self):
        self.assertEqual(format_duration(31536000), "1 year")
        self.assertEqual(format_duration(63072000), "2 years")

    def test_complex_duration(self):
        self.assertEqual(format_duration(31536005), "1 year and 5 seconds")
        self.assertEqual(format_duration(1320302401), "41 years, 1 day, 1 hour, 1 minute, and 1 second")

if __name__ == '__main__':
