class MinStack:
    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, value):
        """Pushes a value onto the stack and updates the minimum stack."""
        self.stack.append(value)
        new_min = value if not self.min_stack else min(value, self.min_stack[-1])
        self.min_stack.append(new_min)

    def pop(self):
        """Removes the top element from the stack and updates the minimum stack."""
        if not self.is_empty():
            self.min_stack.pop()
            return self.stack.pop()
        return None

    def peek(self):
        """Returns the top element of the stack without removing it."""
        if not self.is_empty():
            return self.stack[-1]
        return None

    def is_empty(self):
        """Checks if the stack is empty."""
        return len(self.stack) == 0

    def min(self):
        """Returns the minimum element in the stack."""
        if not self.is_empty():
            return self.min_stack[-1]
        return None
