        """Initialize the bank account with an optional initial balance."""
        self.balance = initial_balance

    def deposit(self, amount):
        """Deposit a specified amount into the account if the amount is positive."""
        if amount > 0:
            self.balance += amount
            print(f"Deposited: ${amount:.2f}. New balance: ${self.balance:.2f}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        """Withdraw a specified amount from the account if sufficient funds are available and the amount is positive."""
        if amount > self.balance:
            print("Insufficient funds. Withdrawal aborted.")
        elif amount <= 0:
            print("Withdrawal amount must be positive.")
        else:
            self.balance -= amount
            print(f"Withdrew: ${amount:.2f}. Remaining balance: ${self.balance:.2f}")

