import threading
from typing import Any, Dict, Optional, List, Tuple

class DataPool:
    def __init__(self):
        """Initialize a thread-safe DataPool with an empty dictionary and a lock."""
        self._data: Dict[str, Any] = {}
        self._lock = threading.Lock()

    def add(self, key: str, value: Any) -> None:
        """Add or update a key with the provided value in the DataPool."""
        with self._lock:
            self._data[key] = value

    def get(self, key: str) -> Optional[Any]:
        """Retrieve the value associated with a key from the DataPool. If the key does not exist, return None."""
        with self._lock:
            return self._data.get(key)

    def remove(self, key: str) -> Optional[Any]:
        """Remove a key from the DataPool and return the corresponding value. If the key does not exist, return None."""
        with self._lock:
            return self._data.pop(key, None)

    def contains(self, key: str) -> bool:
        """Check if a key exists in the DataPool."""
        with self._lock:
            return key in self._data

    def size(self) -> int:
        """Return the number of items currently stored in the DataPool."""
        with self._lock:
            return len(self._data)

    def clear(self) -> None:
        """Clear all items from the DataPool."""
        with self._lock:
            self._data = {}

    def keys(self) -> List[str]:
        """Return a list of all keys in the DataPool."""
        with self._lock:
            return list(self._data.keys())

    def values(self) -> List[Any]:
        """Return a list of all values in the DataPool."""
        with self._lock:
