def medical_record_to_dict(node, use_long_name):
    """
    Converts a hierarchical medical record data structure into a dictionary.

    Args:
        node: The root node of the hierarchical data structure.
        use_long_name: Boolean flag to determine whether to use long names for dictionary keys.

    Returns:
        A dictionary representation of the medical record.
    """
    def build_dict(node, depth, use_long_name):
        node_name = node.long_name if node.long_name and use_long_name else node.name

        if not node.children:
            return (node.data, depth)

        result = {}
        for child in node.children:
            child_name = child.long_name if child.long_name and use_long_name else child.name
            child_dict = build_dict(child, depth + 1, use_long_name)

            if child_name in result:
                if not isinstance(result[child_name], list):
                    result[child_name] = [result[child_name]]
                result[child_name].append(child_dict)
            else:
                result[child_name] = child_dict

        return {key: result[key] for key in sorted(result)}

    return build_dict(node, 0, use_long_name)

