class InventoryManager:
    def __init__(self):
        """Initialize an empty inventory dictionary."""
        self.inventory = {}

    def add_item(self, item_name: str, quantity: int):
        """Add a specified quantity of an item to the inventory.

        Args:
            item_name (str): The name of the item to add.
            quantity (int): The quantity of the item to add.

        Raises:
            ValueError: If the quantity is negative.
        """
        if quantity < 0:
            raise ValueError("Quantity cannot be negative.")
        if item_name in self.inventory:
            self.inventory[item_name] += quantity
        else:
            self.inventory[item_name] = quantity

    def remove_item(self, item_name: str, quantity: int):
        """Remove a specified quantity of an item from the inventory.

        Args:
            item_name (str): The name of the item to remove.
            quantity (int): The quantity of the item to remove.

        Raises:
            ItemNotFoundError: If the item does not exist in the inventory.
            ValueError: If the quantity is negative or exceeds the available quantity.
        """
        if quantity < 0:
            raise ValueError("Quantity cannot be negative.")
        if item_name not in self.inventory:
            raise ItemNotFoundError(item_name)
        if self.inventory[item_name] < quantity:
            raise ValueError(f"Not enough '{item_name}' in inventory to remove {quantity}.")
        self.inventory[item_name] -= quantity
        if self.inventory[item_name] == 0:
            del self.inventory[item_name]  # Remove item if quantity is zero

    def get_inventory(self) -> dict:
        """Return the current state of the inventory.

        Returns:
            dict: The current inventory as a dictionary.
        """
        return self.inventory
